import{z as i,x as n,o as a,c as s,q as e,j as r,D as A,d as t,s as o,S as l}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"风险报告与收束","description":"","frontmatter":{"title":"风险报告与收束","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/rk-reporting-map.md","filePath":"quant/rk-reporting-map.md","lastUpdated":1791413859000}'),C={name:"quant/rk-reporting-map.md"};function p(d,E,D,F,_,h){const B=n("Mermaid");return a(),s("div",null,[E[2]||(E[2]=e('<h1 id="风险报告与收束" tabindex="-1">风险报告与收束 <a class="header-anchor" href="#风险报告与收束" aria-label="Permalink to &quot;风险报告与收束&quot;">​</a></h1><div class="epigraph"><p>风险体系的价值在最后一环兑现：计量变成一份可信的报告，报告变成一次有人签字的决定——没有这一步，前面九环都只是练习。</p><footer>—— 据 Federal Reserve SR 11-7（2011）；BCBS, *Corporate governance principles for banks*, 2015 整理</footer></div><p><a href="/quant/rk-capital-allocation">上一课</a>把资本摊到分部并标上相对价格，激励闭环成形。还剩最后一环：计量与治理的产出要按时、按受众、按责任落到报告与决定——报告是体系的出口，也是回到偏好的入口。本课程到此收束。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>报告环节的病有三类。数据断链：报告数字与源系统对不上，口径没有血缘——每个数字应能回溯到快照时点、模型版本与数据版本，做不到时报告与限额、资本各说各话。受众错配：给董事会看分位数的技术细节，给交易台只发月报——频率与决策节奏不匹配，报告没人读。例外无主：违例、穿透、告警淹没在附录里，没有归因、状态与签字人；报告完成了「分发」，没完成「负责」。错在哪：报告滞后于决策（T+2 出的数字管不住 T+0 的仓）只是表象，根源是报告没有被当成决策流程的一部分，而是当成合规产出。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>分层固定模板与节奏。日度桌面报：限额利用率、回测穿透、最大风险贡献、未解释损益——决策者是桌头与风控，节奏按交易日。月度委员会报：趋势、限额调整、压力测试结果、资本占用与 RAROC 概览、模型例外台账——决策者是风险委员会。季度董事会与监管报：风险偏好达成度、重大例外与处置、模型变更与验证状态。三条纪律贯穿各层。血缘：报告管道与计量流水线同源，数字不可手改，修正走重跑。例外带状态：每个例外必有归因、处置动作、责任人与关闭期限，无状态的例外不许出报告。触发不等周期：限额违例、模型告警、情景越线走即时报，不排队等月度会。</p><p><span class="marginnote">「血缘」可以类比食品包装上的溯源码：报告里每个数字都登记着它来自哪个时点的数据快照、哪个版本的模型。一旦限额利用率和交易台自己的数字对不上，顺着血缘能查到差在数据版本还是模型版本，而不是两边互相甩锅。</span></p>',8)),(a(),r(l,null,{default:A(()=>[o(B,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E6%AF%8F%E5%B1%82%E6%8A%A5%E5%91%8A%EF%BC%9A%E5%A4%9A%E4%B9%85%E5%87%BA%E4%B8%80%E6%AC%A1%E3%80%81%E7%BB%99%E8%B0%81%E7%9C%8B%EF%BC%9F%22%5D%20--%3E%20L1%5B%22%E6%97%A5%E5%BA%A6%E6%A1%8C%E9%9D%A2%E6%8A%A5%EF%BC%9A%E9%99%90%E9%A2%9D%E5%88%A9%E7%94%A8%E7%8E%87%E3%80%81%E7%A9%BF%E9%80%8F%E3%80%81%E6%9C%AA%E8%A7%A3%E9%87%8A%E6%8D%9F%E7%9B%8A%22%5D%0A%20%20Q%20--%3E%20L2%5B%22%E6%9C%88%E5%BA%A6%E5%A7%94%E5%91%98%E4%BC%9A%E6%8A%A5%EF%BC%9A%E8%B6%8B%E5%8A%BF%E3%80%81%E5%8E%8B%E5%8A%9B%E7%BB%93%E6%9E%9C%E3%80%81%E4%BE%8B%E5%A4%96%E5%8F%B0%E8%B4%A6%22%5D%0A%20%20Q%20--%3E%20L3%5B%22%E5%AD%A3%E5%BA%A6%E8%91%A3%E4%BA%8B%E4%BC%9A%E4%B8%8E%E7%9B%91%E7%AE%A1%E6%8A%A5%EF%BC%9A%E5%81%8F%E5%A5%BD%E8%BE%BE%E6%88%90%E5%BA%A6%E3%80%81%E9%87%8D%E5%A4%A7%E5%A4%84%E7%BD%AE%22%5D%0A%20%20L1%20--%3E%20A1%5B%22%E5%8F%97%E4%BC%97%EF%BC%9A%E6%A1%8C%E5%A4%B4%E4%B8%8E%E9%A3%8E%E6%8E%A7%EF%BC%8C%E6%8C%89%E4%BA%A4%E6%98%93%E6%97%A5%22%5D%0A%20%20L2%20--%3E%20A2%5B%22%E5%8F%97%E4%BC%97%EF%BC%9A%E9%A3%8E%E9%99%A9%E5%A7%94%E5%91%98%E4%BC%9A%EF%BC%8C%E6%8C%89%E4%BC%9A%E6%9C%9F%22%5D%0A%20%20L3%20--%3E%20A3%5B%22%E5%8F%97%E4%BC%97%EF%BC%9A%E8%91%A3%E4%BA%8B%E4%BC%9A%E4%B8%8E%E7%9B%91%E7%AE%A1%EF%BC%8C%E6%8C%89%E5%AD%A3%E5%BA%A6%22%5D%0A%20%20L1%20--%3E%7C%22%E9%99%90%E9%A2%9D%E8%BF%9D%E4%BE%8B%E3%80%81%E6%A8%A1%E5%9E%8B%E5%91%8A%E8%AD%A6%22%7C%20T%5B%22%E8%A7%A6%E5%8F%91%E5%BC%8F%E5%8D%B3%E6%97%B6%E6%8A%A5%EF%BC%9A%E4%B8%8D%E7%AD%89%E5%91%A8%E6%9C%9F%22%5D%0A"})]),fallback:A(()=>[...E[0]||(E[0]=[t(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e('<p><span class="marginnote">报告的压缩本身是模型风险：董事会页面只有十格，选哪十个指标进入视野，等于替董事会决定了什么风险「存在」。治理的对策是定期审计这份「指标清单」与偏好陈述的映射，而不是加页。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>为什么报告是闭环的关键：偏好、限额、资本、归因各环的输出只有在报告层对齐，才成为组织的共同事实；签字把「知情」变成「负责」——<a href="/quant/sr-11-7-model-risk">SR 11-7 模型风险管理</a>要求使用侧与开发侧共同担责，落到操作上就是报告签字线。报告也是体系的自检：若日度报出不了 T+1，说明流水线某环太慢或太脆；若例外总在委员会开会时才被发现，说明触发通道名存实亡——诊断体系，先看报告时效与例外流转时间。</p><p><span class="marginnote">初学者容易以为报告晚两天（T+2）只是「慢一点」：实际上 T+2 出的限额利用率管的是前天的仓位，交易台这两天可能已经把仓翻了一遍——报告永远在给不存在的仓位设限。这就是为什么触发式通道要独立于月度会存在。</span></p>',4)),(a(),r(l,null,{default:A(()=>[o(B,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20OUT%5B%22%E5%90%84%E7%8E%AF%E4%BA%A7%E5%87%BA%EF%BC%9A%E8%AE%A1%E9%87%8F%E3%80%81%E5%8E%8B%E5%8A%9B%E3%80%81%E5%BD%92%E5%9B%A0%E3%80%81%E8%B5%84%E6%9C%AC%E3%80%81%E6%A8%A1%E5%9E%8B%E7%8A%B6%E6%80%81%22%5D%20--%3E%20REP%5B%22%E5%88%86%E5%B1%82%E6%8A%A5%E5%91%8A%EF%BC%9A%E6%97%A5%E3%80%81%E6%9C%88%E3%80%81%E5%AD%A3%22%5D%0A%20%20REP%20--%3E%20SIGN%5B%22%E4%BE%8B%E5%A4%96%E5%B8%A6%E7%8A%B6%E6%80%81%EF%BC%8C%E7%AD%BE%E5%AD%97%E5%AE%9A%E8%B4%A3%22%5D%0A%20%20SIGN%20--%3E%20ACT%5B%22%E5%86%B3%E5%AE%9A%EF%BC%9A%E9%99%90%E9%A2%9D%E3%80%81%E8%B5%84%E6%9C%AC%E3%80%81%E6%A8%A1%E5%9E%8B%E5%A4%84%E7%BD%AE%22%5D%0A%20%20ACT%20--%3E%20APP%5B%22%E9%A3%8E%E9%99%A9%E5%81%8F%E5%A5%BD%E4%BF%AE%E8%AE%A2%22%5D%0A%20%20APP%20--%3E%7C%22%E5%9B%9E%E5%88%B0%E7%AC%AC%E4%B8%80%E7%8E%AF%22%7C%20OUT%0A"})]),fallback:A(()=>[...E[1]||(E[1]=[t(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=e('<h2 id="收束" tabindex="-1">收束 <a class="header-anchor" href="#收束" aria-label="Permalink to &quot;收束&quot;">​</a></h2><p>本课程沿两条线走完。计量线四类风险各有生成机制：市场风险把 VaR 与 ES 装进可分环归因的流水线；流动性把退出成本与现金日程分别入账；对手方把暴露画成随市场走的分布；操作风险用频率乘严重度对付重尾与稀样本。治理线六环咬合：模型治理管计量器本身，压力测试覆盖窗口外的联合极端，归因把总量拆成责任，限额把偏好翻译成数字，资本把风险变成价格，报告把一切变成有人签字的决定。体系没有最终完成态：计量会漂移，情景会过时，限额会被磨穿。本课程到此收束。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>报告不创造信息，只压缩与分配注意力；压缩的代价是清单外风险被边缘化，需要反向压力与未遂事件通道补盲。自动化报表不豁免人工审阅：管道不出错不等于口径没错。报告义务因辖区而异，本课给内部治理的最低集，监管模板另加。风险体系为策略服务；策略从生到退的台账与流程治理是下一课程的主题。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>报告按受众与节奏分三层，每层固定模板、固定签字人；频率匹配决策周期。</li><li>每个数字有血缘（快照、模型版本、数据版本）；每个例外有归因、状态与期限。</li><li>触发式报告不等治理周期；报告管道的时效是体系健康的诊断指标。</li><li>体系唯一稳定的性质是环环互检：失效能被看见并回流到偏好与决策。</li><li>出处：Federal Reserve SR 11-7（2011-04-04）与 OCC Bulletin 2011-12；BCBS, <em>Corporate governance principles for banks</em>, 2015；各环细节见本课程前九课与所引 VaR、ES、反向压力测试、SR 11-7 等课。</li></ul>',6))])}const u=i(C,[["render",p]]);export{c as __pageData,u as default};
